// Common pass: Shared musical score, chromatic patterns, and pitch utilities
// Sergei Rachmaninoff's Piano arrangement of "Flight of the Bumblebee" (Complete 104 Measures)

#define BPM 180.0
#define TOTAL_MEASURES 104
#define TOTAL_DURATION (104.0 * (2.0 / 3.0))

bool isBlackKey(int midi) {
    int n = midi % 12;
    return (n == 1 || n == 3 || n == 6 || n == 8 || n == 10);
}

float midiToFreq(float note) {
    return 440.0 * exp2((note - 69.0) / 12.0);
}

// 8-note chromatic patterns (each measure = 8 sixteenth notes in 2/4 time)
float getPatternNote(int patternId, int idx) {
    if (patternId == 0) {
        int p[8] = int[8](71, 70, 69, 68, 69, 70, 71, 72);
        return float(p[idx]);
    } else if (patternId == 1) {
        int p[8] = int[8](73, 74, 75, 76, 77, 76, 75, 74);
        return float(p[idx]);
    } else if (patternId == 2) {
        int p[8] = int[8](73, 72, 71, 70, 69, 68, 69, 70);
        return float(p[idx]);
    } else if (patternId == 3) {
        int p[8] = int[8](71, 72, 73, 74, 75, 76, 77, 78);
        return float(p[idx]);
    } else if (patternId == 4) {
        int p[8] = int[8](79, 78, 77, 76, 75, 74, 73, 72);
        return float(p[idx]);
    } else if (patternId == 5) {
        int p[8] = int[8](71, 70, 69, 68, 67, 66, 65, 64);
        return float(p[idx]);
    } else if (patternId == 6) {
        int p[8] = int[8](63, 64, 65, 66, 67, 68, 69, 70);
        return float(p[idx]);
    } else if (patternId == 7) {
        int p[8] = int[8](77, 76, 75, 74, 73, 74, 75, 76);
        return float(p[idx]);
    } else if (patternId == 8) {
        int p[8] = int[8](83, 82, 81, 80, 81, 82, 83, 84);
        return float(p[idx]);
    } else if (patternId == 9) {
        int p[8] = int[8](85, 86, 87, 88, 89, 88, 87, 86);
        return float(p[idx]);
    } else if (patternId == 10) {
        int p[8] = int[8](85, 84, 83, 82, 81, 80, 81, 82);
        return float(p[idx]);
    } else if (patternId == 11) {
        int p[8] = int[8](83, 84, 85, 86, 87, 88, 89, 90);
        return float(p[idx]);
    } else if (patternId == 12) {
        int p[8] = int[8](91, 90, 89, 88, 87, 86, 85, 84);
        return float(p[idx]);
    } else if (patternId == 13) {
        int p[8] = int[8](83, 82, 81, 80, 79, 78, 77, 76);
        return float(p[idx]);
    } else if (patternId == 14) {
        int p[8] = int[8](75, 76, 77, 78, 79, 80, 81, 82);
        return float(p[idx]);
    } else if (patternId == 15) {
        int p[8] = int[8](75, 74, 73, 72, 71, 70, 69, 68);
        return float(p[idx]);
    } else if (patternId == 16) {
        int p[8] = int[8](67, 66, 65, 64, 63, 62, 61, 60);
        return float(p[idx]);
    } else if (patternId == 17) {
        int p[8] = int[8](59, 60, 61, 62, 63, 64, 65, 66);
        return float(p[idx]);
    } else if (patternId == 18) {
        int p[8] = int[8](67, 68, 69, 70, 71, 72, 73, 74);
        return float(p[idx]);
    } else if (patternId == 19) {
        int p[8] = int[8](75, 76, 77, 78, 79, 80, 81, 82);
        return float(p[idx]);
    } else if (patternId == 20) {
        int p[8] = int[8](83, 84, 85, 86, 87, 88, 89, 90);
        return float(p[idx]);
    } else {
        int p[8] = int[8](83, 82, 81, 80, 81, 81, 81, 81);
        return float(p[idx]);
    }
}

float getLHInversionPattern(int patternId, int idx) {
    if (patternId == 0) {
        int p[8] = int[8](40, 41, 42, 43, 44, 45, 46, 47);
        return float(p[idx]);
    } else if (patternId == 1) {
        int p[8] = int[8](48, 47, 46, 45, 44, 45, 46, 47);
        return float(p[idx]);
    } else if (patternId == 2) {
        int p[8] = int[8](48, 49, 50, 51, 52, 53, 54, 55);
        return float(p[idx]);
    } else {
        int p[8] = int[8](56, 55, 54, 53, 52, 51, 50, 49);
        return float(p[idx]);
    }
}

int getMeasurePatternId(int m) {
    if (m < 8) {
        int pat[8] = int[8](0, 1, 2, 3, 4, 5, 6, 3);
        return pat[m];
    } else if (m < 16) {
        int pat[8] = int[8](0, 1, 2, 3, 4, 5, 6, 3);
        return pat[m - 8];
    } else if (m < 24) {
        int pat[8] = int[8](0, 1, 7, 2, 3, 4, 5, 6);
        return pat[m - 16];
    } else if (m < 32) {
        if (m < 28) return 0;
        int pat[4] = int[4](1, 2, 3, 4);
        return pat[m - 28];
    } else if (m < 40) {
        if (m < 36) return 0;
        int pat[4] = int[4](4, 5, 6, 3);
        return pat[m - 36];
    } else if (m < 52) {
        int pat[12] = int[12](7, 4, 4, 4, 4, 1, 2, 3, 4, 5, 6, 3);
        return pat[m - 40];
    } else if (m < 64) {
        if (m < 60) return 0;
        int pat[4] = int[4](6, 3, 0, 1);
        return pat[m - 60];
    } else if (m < 72) {
        int pat[8] = int[8](1, 2, 3, 4, 5, 6, 0, 1);
        return pat[m - 64];
    } else if (m < 80) {
        int pat[8] = int[8](2, 3, 4, 5, 6, 3, 0, 1);
        return pat[m - 72];
    } else if (m < 84) {
        int pat[4] = int[4](2, 3, 4, 14);
        return pat[m - 80];
    } else if (m < 92) {
        int pat[8] = int[8](8, 9, 10, 11, 12, 13, 14, 11);
        return pat[m - 84];
    } else if (m < 100) {
        int pat[8] = int[8](12, 13, 15, 16, 17, 18, 19, 20);
        return pat[m - 92];
    } else {
        int pat[4] = int[4](12, 21, 0, 0);
        return pat[m - 100];
    }
}

float getActiveScoreNote(int measure, int stepInMeasure) {
    if (measure >= 52 && measure < 60) {
        return getLHInversionPattern((measure - 52) % 4, stepInMeasure);
    } else if ((measure >= 24 && measure < 28) || (measure >= 32 && measure < 36)) {
        return (measure % 4 == 0) ? 81.0 : ((measure % 4 == 1) ? 83.0 : ((measure % 4 == 2) ? 81.0 : 86.0));
    } else {
        return getPatternNote(getMeasurePatternId(measure), stepInMeasure);
    }
}

// Il volo del calabrone - Visual Flight Pass
// Animated golden flight trajectory of the bumblebee in sync with the 180 BPM piano performance
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.y, iResolution.x);

    float dist = length(uv);
    vec3 bg = mix(vec3(0.08, 0.04, 0.02), vec3(0.015, 0.008, 0.01), dist);

    // 180 BPM Presto score timing
    float pTime = mod(iTime, TOTAL_DURATION);
    float beat = pTime * (BPM / 60.0);
    float sixteenth = beat * 4.0;
    float beatPulse = exp(-6.0 * fract(beat));

    int totalStep16 = int(floor(pTime * 12.0));
    int measure = totalStep16 / 8;
    int stepInMeasure = totalStep16 % 8;
    float activeNote = getActiveScoreNote(measure, stepInMeasure);
    float pitchNorm = clamp((activeNote - 60.0) / 30.0, -0.5, 0.5);

    vec3 col = bg;

    // 3 spiraling golden flight trails of the bumblebee, buzzing to the piano notes
    for (int k = 0; k < 3; k++) {
        float delay = float(k) * 0.08;
        float t = (iTime - delay) * 4.5;

        vec2 beePos = vec2(
            0.45 * sin(t * 1.5 + float(k) * 0.5) * cos(t * 0.5),
            0.28 * sin(t * 3.0) + pitchNorm * 0.25
        );

        float d = length(uv - beePos);
        float glow = 0.004 / (d * d + 0.001);
        vec3 trailCol = mix(vec3(1.0, 0.7, 0.1), vec3(1.0, 0.9, 0.3), float(k) * 0.3);
        col += trailCol * glow * (1.0 - float(k) * 0.25);
    }

    // Swirling golden pollen particles
    for (int i = 0; i < 8; i++) {
        float fi = float(i);
        float a = fi * 0.785 + iTime * 2.0;
        float r = 0.15 + 0.18 * sin(iTime * 3.0 + fi * 1.5);
        vec2 p = vec2(cos(a), sin(a)) * r;
        float pd = length(uv - p);
        col += vec3(1.0, 0.8, 0.2) * (0.0008 / (pd * pd + 0.0005));
    }

    // Concentric acoustic ripples pulsing to the 2/4 piano beat
    float ripple = sin(dist * 30.0 - iTime * 12.0);
    col += vec3(0.8, 0.5, 0.1) * smoothstep(0.75, 1.0, ripple) * 0.18 * beatPulse;

    col *= 1.0 - 0.45 * dist * dist;
    fragColor = vec4(col, 1.0);
}
